mapper.select:
select BEAD_CODE, SUM(IFNULL(STOCK_NUM,0)+IFNULL(MODIFY_NUM,0)-IFNULL(BAD_NUM,0)) STOCK_NUM from T_TQ_STOCK where STOCK_DATE = DATE_ADD(#{stockDate}, INTERVAL -1 day) /*排程日期 要减1天，才是对应库存日期*/ and IS_DELETE = '0'
and FACTORY_CODE = #{factoryCode}
GROUP BY BEAD_CODE

SELECT BEAD_CODE, IFNULL(SUM(CLASS3_PLAN_QTY), 0) consume FROM T_TQ_SCHEDULE_RESULT WHERE SCHEDULE_DATE = DATE_ADD(#{scheduleDate}, INTERVAL -1 day) AND IS_DELETE = 0
AND FACTORY_CODE = #{factoryCode}
GROUP BY BEAD_CODE
